from fastapi import FastAPI, Request, Depends, HTTPException
from fastapi.responses import JSONResponse

app = FastAPI()

class CollateralValuationError(Exception):
    def __init__(self, application_id: str):
        self.application_id = application_id

@app.exception_handler(CollateralValuationError)
async def valuation_error_handler(request: Request, exc: CollateralValuationError):
    return JSONResponse(
        status_code=422,
        content={
            "message": "Collateral asset failed automated LTV threshold appraisal",
            "application_id": exc.application_id
        }
    )

@app.post("/loans/applications/{application_id}/collateral/evaluate")
async def evaluate_collateral(
    application_id: str,
    loan_svc: LoanService = Depends(get_loan_service),
    user: LoanBroker = Depends(get_current_broker)
):
    loan = await loan_svc.get_application(application_id)
    if not loan:
        raise HTTPException(status_code=404, detail="Application not found")
    if loan.broker_id != user.id and not user.is_chief_underwriter:
        raise HTTPException(status_code=403, detail="Forbidden: broker is not assigned to this loan application")

    if not await loan_svc.verify_ltv_ratios(loan):
        raise CollateralValuationError(application_id)

    return {"status": "valuation_approved", "application_id": application_id}
